{"type":"message","id":"d14edaf4","parentId":"b90abe54","timestamp":"2026-06-01T16:26:31.354Z","message":{"role":"toolResult","toolCallId":"pT8Nr894pALhCK6drFpHRwXqzl6WwSde","toolName":"read","content":[{"type":"text","text":"import { create } from 'zustand'

// ============================================================================
// Types
// ============================================================================

/** A part from the catalog, ready to be added to cart */
export interface PartCatalogItem {
  id: string
  barcode: string
  name: string
  priceNet: number // in cents (integer)
  quantityOnHand: number
}

/** VAT rate ID constants — matches server vatRates table */
export const VAT_RATES = {
  'vat-standard': 2100, // 21%
  'vat-reduced': 600,   // 6%
  'vat-zero': 0,        // 0%
} as const

/** Default VAT rate for parts */
export const DEFAULT_VAT_RATE = 'vat-standard' as const

/** A single line item in the cart */
export interface CartLineItem {
  partId: string
  barcode: string
  name: string
  priceNet: number // ex-tax cents per unit (snapshot at add time)
  quantity: number
  vatRateId: keyof typeof VAT_RATES
  discountPercent: number | null // basis points, e.g. 1000 = 10%
  // Computed totals (updated whenever qty/discount changes)
  lineTotalNet: number
  lineTotalVat: number
  lineTotalGross: number
}

/** Customer selector item from GET /customers (search response) */
export interface CustomerSelectorItem {
  id: string
  displayName: string
  type: 'private' | 'company'
  email?: string | null
  phone?: string | null
}

/** Payload sent to POST /sales for checkout */
export interface CheckoutPayload {
  customerId: string | null
  paymentMethod: 'cash' | 'card'
  lineItems: Array<{
    partId: string
    quantity: number
    unitPriceNet: number
    vatRateId: string
    description: string
  }>
}

/** Success info returned from POST /sales */
export interface CheckoutSuccess {
  saleNumber: string
  totalGross: number
}

// ============================================================================
// Helpers — Line item math (all amounts in cents, integer)
// ============================================================================

/**
 * Compute line totals from quantity, unit price, discount, and VAT rate.
 *
 * Formula: discountedNetPerUnit = unitPriceNet × (1 - discountBps / 10000)
 *          lineNetTotal = discountedNetPerUnit × quantity
 *          lineVatTotal = round(lineNetTotal × vatRateBps / 10000)
 *          lineGrossTotal = lineNetTotal + lineVatTotal
 */
function computeLineTotals(
  priceNet: number,
  quantity: number,
  discountPercentBps: number | null,
  vatRateBps: number
): { net: number; vat: number; gross: number } {
  const discountFactor = discountPercentBps ? 1 - discountPercentBps / 10000 : 1
  const discountedNetPerUnit = Math.round(priceNet * discountFactor)
  const lineNetTotal = discountedNetPerUnit * quantity
  const lineVatTotal = Math.round(lineNetTotal * vatRateBps / 10000)

  return { net: lineNetTotal, vat: lineVatTotal, gross: lineNetTotal + lineVatTotal }
}

// ============================================================================
// Store
// ============================================================================

interface PosCartState {
  // Line items in the cart
  lineItems: CartLineItem[]

  // Selected customer (null = walk-in)
  customerId: string | null

  // Checkout state
  checkoutError: string | null
  checkoutSuccess: CheckoutSuccess | null
  isCheckingOut: boolean

  // Computed totals (derived from line items)
  subtotalNet: number
  vatTotal: number
  totalGross: number

  // Whether the cart can be checked out
  canCheckout: boolean
}

interface PosCartActions {
  // Line item operations
  addLineItem: (part: PartCatalogItem, quantity?: number) => void
  removeLineItem: (partId: string) => void
  updateQuantity: (partId: string, quantity: number) => void
  applyDiscount: (partId: string, discountPercentBps: number) => void
  changeVatRate: (partId: string, newVatRateId: keyof typeof VAT_RATES) => void

  // Customer selection
  setCustomer: (customerId: string | null) => void

  // Checkout state management
  clearCart: () => void
  clearErrors: () => void
  startCheckout: () => void
  finishCheckout: (success: CheckoutSuccess) => void
  failCheckout: (error: string) => void
  setCheckoutError: (error: string | null) => void
  setCheckoutSuccess: (success: CheckoutSuccess | null) => void

  // Get checkout payload for API call
  getCheckoutPayload: () => CheckoutPayload
}

export type PosCartStore = PosCartState & PosCartActions

const initialState: PosCartState = {
  lineItems: [],
  customerId: null,
  checkoutError: null,
  checkoutSuccess: null,
  isCheckingOut: false,
  subtotalNet: 0,
  vatTotal: 0,
  totalGross: 0,
  canCheckout: false,
}

function computeTotals(lineItems: CartLineItem[]): { subtotalNet: number; vatTotal: number; totalGross: number } {
  let subtotalNet = 0
  let vatTotal = 0

  for (const item of lineItems) {
    const vatRateBps = VAT_RATES[item.vatRateId] ?? 2100
    const totals = computeLineTotals(item.priceNet, item.quantity, item.discountPercent, vatRateBps)
    subtotalNet += totals.net
    vatTotal += totals.vat
  }

  return { subtotalNet, vatTotal, totalGross: subtotalNet + vatTotal }
}

/** Compute line-level totals for a single cart item */
function computeItemTotals(item: {
  priceNet: number
  quantity: number
  discountPercent: number | null
  vatRateId: keyof typeof VAT_RATES
}): Pick<CartLineItem, 'lineTotalNet' | 'lineTotalVat' | 'lineTotalGross'> {
  const vatRateBps = VAT_RATES[item.vatRateId] ?? 2100
  const { net, vat, gross } = computeLineTotals(item.priceNet, item.quantity, item.discountPercent, vatRateBps)
  return { lineTotalNet: net, lineTotalVat: vat, lineTotalGross: gross }
}

function updateComputedState(state: PosCartStore): Partial<PosCartState> {
  const totals = computeTotals(state.lineItems)
  return {
    ...totals,
    canCheckout: state.lineItems.length > 0,
  }
}

export const useCartStore = create<PosCartStore>((set, get) => ({
  ...initialState,

  // ── Line Item Operations ────────────────────────────────────────

  addLineItem: (part, quantity = 1) => {
    set((state) => {
      // If quantity is 0 or less, remove existing line item
      if (quantity <= 0) {
        const newItems = state.lineItems.filter((item) => item.partId !== part.id)
        return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
      }

      const existingIndex = state.lineItems.findIndex((item) => item.partId === part.id)

      let newItems: CartLineItem[]

      if (existingIndex >= 0) {
        // Increment quantity for existing line item
        const existingItem = state.lineItems[existingIndex]
        const newQty = existingItem.quantity + quantity
        newItems = [...state.lineItems]
        newItems[existingIndex] = {
          ...existingItem,
          quantity: newQty,
          ...computeItemTotals({ priceNet: existingItem.priceNet, quantity: newQty, discountPercent: existingItem.discountPercent, vatRateId: existingItem.vatRateId }),
        }
      } else {
        // Add new line item
        const totals = computeItemTotals({ priceNet: part.priceNet, quantity, discountPercent: null, vatRateId: DEFAULT_VAT_RATE })
        const newItem: CartLineItem = {
          partId: part.id,
          barcode: part.barcode,
          name: part.name,
          priceNet: part.priceNet,
          quantity,
          vatRateId: DEFAULT_VAT_RATE,
          discountPercent: null,
          ...totals,
        }
        newItems = [...state.lineItems, newItem]
      }

      return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
    })
  },

  removeLineItem: (partId) => {
    set((state) => {
      const newItems = state.lineItems.filter((item) => item.partId !== partId)
      return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
    })
  },

  updateQuantity: (partId, quantity) => {
    set((state) => {
      // Remove if quantity is exactly 0
      if (quantity === 0) {
        const newItems = state.lineItems.filter((item) => item.partId !== partId)
        return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
      }

      // Clamp to minimum of 1 (negative values become 1)
      const clampedQty = Math.max(1, quantity)

      const newItems = state.lineItems.map((item) =>
        item.partId === partId
          ? { ...item, quantity: clampedQty, ...computeItemTotals({ ...item, quantity: clampedQty }) }
          : item
      )

      return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
    })
  },

  applyDiscount: (partId, discountPercentBps) => {
    set((state) => {
      const newItems = state.lineItems.map((item) =>
        item.partId === partId
          ? { ...item, discountPercent: discountPercentBps, ...computeItemTotals({ ...item, discountPercent: discountPercentBps }) }
          : item
      )
      return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
    })
  },

  changeVatRate: (partId, newVatRateId) => {
    set((state) => {
      const newItems = state.lineItems.map((item) =>
        item.partId === partId
          ? { ...item, vatRateId: newVatRateId, ...computeItemTotals({ ...item, vatRateId: newVatRateId }) }
          : item
      )
      return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
    })
  },

  // ── Customer Selection ──────────────────────────────────────────

  setCustomer: (customerId) => {
    set({ customerId })
  },

  // ── Checkout State Management ───────────────────────────────────

  clearCart: () => {
    set({ ...initialState, lineItems: [], customerId: null })
  },

  clearErrors: () => {
    set({ checkoutError: null, checkoutSuccess: null })
  },

  startCheckout: () => {
    set({ isCheckingOut: true, checkoutError: null })
  },

  failCheckout: (error) => {
    set({ isCheckingOut: false, checkoutError: error })
  },

  setCheckoutError: (error) => {
    set({ checkoutError: error })
  },

  setCheckoutSuccess: (success) => {
    set({ checkoutSuccess: success })
  },

  finishCheckout: (success) => {
    set({
      isCheckingOut: false,
      checkoutSuccess: success,
      lineItems: [],
      customerId: null,
      subtotalNet: 0,
      vatTotal: 0,
      totalGross: 0,
      canCheckout: false,
    })
  },

  // ── Checkout Payload Builder ────────────────────────────────────

  getCheckoutPayload: (): CheckoutPayload => {
    const state = get()
    return {
      customerId: state.customerId,
      paymentMethod: 'cash', // default — can be overridden by caller
      lineItems: state.lineItems.map((item) => ({
        partId: item.partId,
        quantity: item.quantity,
        unitPriceNet: item.priceNet,
        vatRateId: item.vatRateId,
        description: item.name,
      })),
    }
  },
}))
